package com.rescuemate.data

/**
 * Medical Data Database
 * Parsed from the provided CSV dataset (e04356c7.csv)
 * Contains structured data for medical conditions, medications, and allergies
 */

// Data classes for medical data
data class MedicalConditionData(
    val name: String,
    val category: String,
    val type: String,
    val description: String,
    val symptoms: String,
    val severity: String = "",
    val management: String = ""
)

data class MedicationData(
    val name: String,
    val drugClass: String,
    val usesIndications: String,
    val mechanismOfAction: String,
    val commonSideEffects: String,
    val seriousWarnings: String
)

data class AllergyData(
    val name: String,
    val description: String,
    val allergen: String,
    val severity: String,
    val management: String
)

