        // Parse the CSV data
        val lines = csvData.lines()
        val header = lines.first().split(",")

        for (line in lines.drop(1)) {
            if (line.trim().isEmpty()) continue

            val columns = parseCSVLine(line)
            if (columns.size < 16) continue

            when (columns[0]) {
                "MEDICAL CONDITIONS" -> {
                    medicalConditionsList.add(
                        MedicalConditionData(
                            name = columns[1],
                            category = columns[2],
                            type = columns[3],
                            description = columns[4],
                            symptoms = columns[5],
                            severity = columns[9],
                            management = columns[10]
                        )
                    )
                }
                "MEDICATIONS" -> {
                    medicationsList.add(
                        MedicationData(
                            name = columns[1],
                            drugClass = columns[9],
                            usesIndications = columns[10],
                            mechanismOfAction = columns[11],
                            commonSideEffects = columns[12],
                            seriousWarnings = columns[13]
                        )
                    )
                }
                "ALLERGIES" -> {
                    allergiesList.add(
                        AllergyData(
                            name = columns[1],
                            description = columns[2],
                            allergen = columns[8],
                            severity = columns[9],
                            management = columns[10]
                        )
                    )
                }
            }
        }
    }

    /**
     * Simple CSV parser that handles quoted fields
     */
    private fun parseCSVLine(line: String): List<String> {
        val result = mutableListOf<String>()
        var current = StringBuilder()
        var inQuotes = false

        for (i in line.indices) {
            val char = line[i]
            when {
                char == '"' && !inQuotes -> {
                    inQuotes = true
                }
                char == '"' && inQuotes && i < line.length - 1 && line[i + 1] == '"' -> {
                    // Escaped quote
                    current.append('"')
                }
                char == '"' && inQuotes -> {
                    inQuotes = false
                }
                char == ',' && !inQuotes -> {
                    result.add(current.toString().trim())
                    current = StringBuilder()
                }
                else -> {
                    current.append(char)
                }
            }
        }
        result.add(current.toString().trim())
        return result
    }

    // Public access methods
    fun getMedicalConditions(): List<MedicalConditionData> = medicalConditionsList
    fun getMedications(): List<MedicationData> = medicationsList
    fun getAllergies(): List<AllergyData> = allergiesList

    // Search methods for autocomplete
    fun searchMedicalConditions(query: String): List<MedicalConditionData> {
        if (query.isBlank()) return emptyList()
        return medicalConditionsList.filter {
            it.name.contains(query, ignoreCase = true) ||
            it.description.contains(query, ignoreCase = true)
        }
    }

    fun searchMedications(query: String): List<MedicationData> {
        if (query.isBlank()) return emptyList()
        return medicationsList.filter {
            it.name.contains(query, ignoreCase = true) ||
            it.drugClass.contains(query, ignoreCase = true)
        }
    }

    fun searchAllergies(query: String): List<AllergyData> {
        if (query.isBlank()) return emptyList()
        return allergiesList.filter {
            it.name.contains(query, ignoreCase = true) ||
            it.description.contains(query, ignoreCase = true)
        }
    }
